(1, 142, 8, 'Điểm số này theo tôi là công bằng. Cuốn sách có điểm mạnh và điểm yếu khá rõ ràng.', 'approved', 1, '2025-01-18 06:28:04', '2025-01-16 20:17:04', NULL),
(2, 199, 149, 'Một trải nghiệm xem đáng nhớ trong năm nay. Rất đáng để xem lại lần thứ hai.', 'approved', 2, '2025-01-18 06:25:12', '2025-01-17 19:34:12', NULL),
(3, 110, 71, 'Một trải nghiệm xem đáng nhớ trong năm nay. Bộ phim có cốt truyện chặt chẽ và nhiều lớp ý nghĩa.', 'approved', 2, '2025-02-05 02:41:02', '2025-02-03 06:30:02', NULL),
(4, 22, 155, 'Nhân vật được xây dựng có chiều sâu, cảm xúc rất thật. Phần kết khiến tôi suy nghĩ rất lâu.', 'approved', 1, '2025-02-06 20:59:35', '2025-02-05 00:56:35', NULL),
(5, 79, 262, 'Nhân vật được xây dựng có chiều sâu, cảm xúc rất thật.', 'approved', 1, '2025-02-10 21:48:25', '2025-02-09 10:53:25', NULL),
(6, 151, 8, 'Khó có thể giới thiệu cuốn sách này cho người khác. Kỳ vọng nhiều hơn những gì cuốn sách mang lại. Tôi đã mong chờ nhiều hơn khi đọc đến đoạn cuối.', 'approved', 3, '2025-02-14 20:45:41', '2025-02-14 06:21:41', NULL),
(7, 286, 149, 'Nửa đầu cuốn hút hơn nửa sau. Bộ phim có điểm mạnh và điểm yếu khá rõ ràng.', 'approved', 3, '2025-02-18 08:51:47', '2025-02-16 20:23:47', NULL),
